function obterMesAnoAtualCarro() {
  var d = new Date();
  return { ano: d.getFullYear(), mes: d.getMonth(), hojeIso: obterDataHojeIso() };
}

function adicionarDiasIso(dataIso, deltaDias) {
  var p = String(dataIso || obterDataHojeIso()).split('-');
  var d = new Date(parseInt(p[0], 10), parseInt(p[1], 10) - 1, parseInt(p[2], 10), 12, 0, 0);
  d.setDate(d.getDate() + deltaDias);
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
}

