/* ============================================================== */
/* MOTOR DE AVISOS E CONFIRMAÇÕES UX/UI CENTRALIZADO (ZERO ALERT) */
/* ============================================================== */

let __carroUxConfirmCallback = null;

function fecharModalAvisoCarroUX() {
  const modal = document.getElementById('modal-aviso-carro-ux');
  if (modal) modal.style.display = 'none';
  __carroUxConfirmCallback = null;
}

function executarAcaoPrimariaAvisoCarroUX() {
  if (typeof __carroUxConfirmCallback === 'function') {
    const fn = __carroUxConfirmCallback;
    const result = fn();
    if (result !== false) {
      fecharModalAvisoCarroUX();
    }
  } else {
    fecharModalAvisoCarroUX();
  }
}

function abrirModalAvisoCarroUX(opts) {
  const modal = document.getElementById('modal-aviso-carro-ux');
  if (!modal) return;
  const headerEl = document.getElementById('ux-carro-modal-header');
  const iconEl = document.getElementById('ux-carro-modal-icon');
  const eyeEl = document.getElementById('ux-carro-modal-eyebrow');
  const titleEl = document.getElementById('ux-carro-modal-title');
  const bodyEl = document.getElementById('ux-carro-modal-body');
  const primaryBtn = document.getElementById('ux-carro-modal-btn-primary');
  const closeBtnText = document.getElementById('ux-carro-modal-btn-close-text');

  const tipo = (opts && opts.tipo) || 'aviso';
  const paleta = tipo === 'conflito' || tipo === 'perigo'
    ? { border: '#ef4444', badgeBg: 'rgba(239, 68, 68, 0.2)', badgeColor: '#fca5a5', icon: (opts && opts.icone) || '⚠️', eyeColor: '#fca5a5' }
    : (tipo === 'sucesso' || tipo === 'concluir'
      ? { border: '#10b981', badgeBg: 'rgba(16, 185, 129, 0.2)', badgeColor: '#6ee7b7', icon: (opts && opts.icone) || '🏁', eyeColor: '#6ee7b7' }
      : { border: '#f09b0c', badgeBg: 'rgba(240, 155, 12, 0.2)', badgeColor: '#fde047', icon: (opts && opts.icone) || '💡', eyeColor: '#fde047' });

  if (headerEl) headerEl.style.borderBottom = '3px solid ' + paleta.border;
  if (iconEl) {
    iconEl.innerText = paleta.icon;
    iconEl.style.background = paleta.badgeBg;
    iconEl.style.color = paleta.badgeColor;
    iconEl.style.borderColor = paleta.border;
  }
  if (eyeEl) {
    eyeEl.innerText = (opts && opts.eyebrow) || 'AVISO DO SISTEMA • FROTA OFICIAL';
    eyeEl.style.color = paleta.eyeColor;
  }
  if (titleEl) titleEl.innerText = (opts && opts.titulo) || 'Atenção';
  if (bodyEl) bodyEl.innerHTML = (opts && opts.html) || '';
  if (closeBtnText) closeBtnText.innerText = (opts && opts.textoFechar) || 'Fechar';

  __carroUxConfirmCallback = (opts && typeof opts.onConfirmar === 'function') ? opts.onConfirmar : null;
  if (primaryBtn) {
    if (opts && opts.textoConfirmar && __carroUxConfirmCallback) {
      primaryBtn.style.display = 'inline-flex';
      primaryBtn.innerHTML = '<span>' + escaparHtmlSimples(opts.textoConfirmar) + '</span>';
      if (tipo === 'perigo') {
        primaryBtn.style.background = 'linear-gradient(135deg, #dc2626 0%, #b91c1c 100%)';
        primaryBtn.style.borderColor = '#991b1b';
        primaryBtn.style.color = '#ffffff';
      } else if (tipo === 'concluir') {
        primaryBtn.style.background = 'linear-gradient(135deg, #059669 0%, #047857 100%)';
        primaryBtn.style.borderColor = '#065f46';
        primaryBtn.style.color = '#ffffff';
      } else {
        primaryBtn.style.background = 'linear-gradient(135deg, #0b2351 0%, #1e40af 100%)';
        primaryBtn.style.borderColor = '#f09b0c';
        primaryBtn.style.color = '#ffffff';
      }
    } else {
      primaryBtn.style.display = 'none';
    }
  }

  modal.style.display = 'flex';
}

