/* CRUD E MODAIS: SOLICITAÇÃO MEGA-PREMIUM, EDIÇÃO E FROTA        */
/* ============================================================== */

function solicitarCarroParaVeiculo(placa) {
  abrirModalNovaSolicitacaoCarro(placa, dataAtivaCarro);
}

function popularDatalistEscolasCarro() {
  const dl = document.getElementById('carro-destinos-escolas-list');
  if (!dl) return;
  const opcoes = [
    'SEDUC - Praça da República, 53 - São Paulo',
    'URE - ITP - Rua Dimarães Antônio Sandei, 75',
    'Prefeitura Municipal de Itapevi',
    'Prefeitura Municipal de Barueri',
    'Prefeitura Municipal de Jandira',
    'Prefeitura de Pirapora do Bom Jesus'
  ];
  try {
    if (typeof listaEscolas !== 'undefined' && Array.isArray(listaEscolas)) {
      listaEscolas.forEach(function(e) {
        if (e && e.nome) opcoes.push(String(e.nome).replace(/^E\.?E\.?\s+/i, '') + (e.cidade ? ' (' + e.cidade + ')' : ''));
      });
    }
  } catch(err) {}
  dl.innerHTML = opcoes.map(function(o) {
    return '<option value="' + escaparHtmlSimples(o) + '"></option>';
  }).join('');
}

function abrirModalNovaSolicitacaoCarro(placaPredefinida, dataPredefinida) {
  const modal = document.getElementById('modal-solicitar-carro');
  if (!modal) return;

  popularDatalistEscolasCarro();

  const form = document.getElementById('form-nova-solicitacao-carro');
  if (form) form.reset();
  const inMotReset = document.getElementById('form-carro-motorista');
  if (inMotReset) delete inMotReset.dataset.editadoManual;

  const dataBaseSol = dataPredefinida || dataAtivaCarro || obterDataHojeIso();
  const inputData = document.getElementById('form-carro-data');
  if (inputData) inputData.value = dataBaseSol;
  const inputDataRet = document.getElementById('form-carro-data-retorno');
  if (inputDataRet) {
    inputDataRet.value = dataBaseSol;
    inputDataRet.min = dataBaseSol;
    delete inputDataRet.dataset.editadoManual;
  }

  const inSaida = document.getElementById('form-carro-saida');
  const inRetorno = document.getElementById('form-carro-retorno');
  if (inSaida && !inSaida.value) inSaida.value = '08:00';
  if (inRetorno && !inRetorno.value) inRetorno.value = '17:00';

  const inApr = document.getElementById('form-carro-apresentar');
  if (inApr) inApr.value = 'URE - ITP - Rua Dimarães Antônio Sandei, 75';

  const valVeiculo = (placaPredefinida && placaPredefinida.indexOf('FZG') !== -1)
    ? 'Hyundai HB20 1.0 (Oficial Apoio)'
    : 'Chevrolet Spin 1.8 7L (Oficial Gabinete)';

  selecionarVeiculoSolicitacaoCarro(valVeiculo);
  modal.style.display = 'flex';
}

function fecharModalCarro() {
  const modal = document.getElementById('modal-solicitar-carro');
  if (modal) modal.style.display = 'none';
}

function selecionarVeiculoSolicitacaoCarro(valorVeiculo) {
  const selVeiculo = document.getElementById('form-carro-veiculo');
  if (selVeiculo) selVeiculo.value = valorVeiculo;

  const cardSpin = document.getElementById('req-card-veiculo-spin');
  const cardHb20 = document.getElementById('req-card-veiculo-hb20');
  const isSpin = String(valorVeiculo || '').indexOf('Spin') !== -1;

  if (cardSpin) cardSpin.classList.toggle('selected', isSpin);
  if (cardHb20) cardHb20.classList.toggle('selected', !isSpin);

  atualizarCamposVeiculoFormularioNovo();
  verificarDisponibilidadeModalSolicitacao();
}

function aplicarPeriodoRapidoCarro(saida, retorno) {
  const inSaida = document.getElementById('form-carro-saida');
  const inRetorno = document.getElementById('form-carro-retorno');
  if (inSaida) inSaida.value = saida;
  if (inRetorno) inRetorno.value = retorno;
  verificarDisponibilidadeModalSolicitacao();
}

function aplicarDestinoRapidoCarro(dest) {
  const inDest = document.getElementById('form-carro-destino');
  const inItin = document.getElementById('form-carro-itinerario');
  if (inDest) inDest.value = dest;
  if (inItin) inItin.value = 'URE - ITP -> ' + dest + ' -> Retorno URE - ITP';
}

function atualizarItinerarioAutomaticoCarro() {
  const inDest = document.getElementById('form-carro-destino');
  const inItin = document.getElementById('form-carro-itinerario');
  if (!inDest || !inItin) return;
  if (!inItin.dataset.editadoManual) {
    inItin.value = inDest.value.trim()
      ? ('URE - ITP -> ' + inDest.value.trim() + ' -> Retorno URE - ITP')
      : '';
  }
}

function aoMudarDataIdaSolicitacaoCarro() {
  const inDataIda = document.getElementById('form-carro-data');
  const inDataRet = document.getElementById('form-carro-data-retorno');
  if (inDataIda && inDataRet && inDataIda.value) {
    inDataRet.min = inDataIda.value;
    if (!inDataRet.dataset.editadoManual || !inDataRet.value || inDataRet.value < inDataIda.value) {
      inDataRet.value = inDataIda.value;
    }
  }
  verificarDisponibilidadeModalSolicitacao();
}

function verificarDisponibilidadeModalSolicitacao() {
  const data = document.getElementById('form-carro-data') ? document.getElementById('form-carro-data').value : obterDataHojeIso();
  const inDataRet = document.getElementById('form-carro-data-retorno');
  const dataRetorno = (inDataRet && inDataRet.value) ? inDataRet.value : data;
  const saida = document.getElementById('form-carro-saida') ? document.getElementById('form-carro-saida').value : '08:00';
  const retorno = document.getElementById('form-carro-retorno') ? document.getElementById('form-carro-retorno').value : '17:00';
  const selVeiculo = document.getElementById('form-carro-veiculo');
  const isSpinSel = selVeiculo ? selVeiculo.value.indexOf('Spin') !== -1 : true;
  const placaSel = isSpinSel ? 'TLH 1B63' : 'FZG 0H22';

  const durEl = document.getElementById('form-carro-duracao-badge');
  if (durEl) {
    const dur = calcularDuracaoViagemCompleta(data, saida, dataRetorno, retorno);
    durEl.innerText = dur === '--' ? '⚠️ Verifique datas e horários' : ('⏱️ Duração: ' + dur);
    durEl.style.color = dur === '--' ? '#b91c1c' : '#1e40af';
  }

  const confSpin = verificarConflitoAgendaCarro(data, saida, retorno, 'TLH 1B63', null, dataRetorno);
  const confHb20 = verificarConflitoAgendaCarro(data, saida, retorno, 'FZG 0H22', null, dataRetorno);

  const cardSpin = document.getElementById('req-card-veiculo-spin');
  const cardHb20 = document.getElementById('req-card-veiculo-hb20');
  const stSpin = document.getElementById('req-status-veiculo-spin');
  const stHb20 = document.getElementById('req-status-veiculo-hb20');

  if (cardSpin) cardSpin.classList.toggle('has-conflict', confSpin.temConflito);
  if (cardHb20) cardHb20.classList.toggle('has-conflict', confHb20.temConflito);

  if (stSpin) {
    stSpin.innerHTML = confSpin.temConflito
      ? '<span style="color: #dc2626; font-weight: 800;">🔴 Ocupado neste horário</span>'
      : '<span style="color: #059669; font-weight: 800;">🟢 Livre no horário</span>';
  }
  if (stHb20) {
    stHb20.innerHTML = confHb20.temConflito
      ? '<span style="color: #dc2626; font-weight: 800;">🔴 Ocupado neste horário</span>'
      : '<span style="color: #059669; font-weight: 800;">🟢 Livre no horário</span>';
  }

  const box = document.getElementById('form-carro-disponibilidade-box');
  if (!box) return;

  const confAtiva = isSpinSel ? confSpin : confHb20;
  const outroLivre = isSpinSel ? !confHb20.temConflito : !confSpin.temConflito;
  const outroNome = isSpinSel ? 'Hyundai HB20 1.0 (FZG 0H22)' : 'Chevrolet Spin 1.8 7L (TLH 1B63)';
  const outroValor = isSpinSel ? 'Hyundai HB20 1.0 (Oficial Apoio)' : 'Chevrolet Spin 1.8 7L (Oficial Gabinete)';

  if (confAtiva.temConflito) {
    const c = confAtiva.conflitantes[0];
    box.style.background = '#fef2f2';
    box.style.borderColor = '#fca5a5';
    box.innerHTML = `
      <div style="display: flex; justify-content: space-between; align-items: center; gap: 0.75rem; flex-wrap: wrap;">
        <div style="font-size: 0.8rem; color: #991b1b;">
          <strong>⚠️ Conflito de Agenda Detectado para ${placaSel}:</strong>
          Já existe reserva das <strong>${formatarDataCurtaBr(c.data)} ${c.horarioSaida} às ${formatarDataCurtaBr(c.dataRetorno || c.data)} ${c.horarioRetorno}</strong> para <em>${escaparHtmlSimples(c.solicitante)} (${escaparHtmlSimples(c.unidade || c.setor || 'URE')})</em>.
        </div>
        ${outroLivre ? `<button type="button" onclick="selecionarVeiculoSolicitacaoCarro('${outroValor}')" style="background: #0b2351; color: #fde047; border: none; border-radius: 6px; padding: 0.35rem 0.7rem; font-size: 0.75rem; font-weight: 800; cursor: pointer;">Trocar para ${outroNome}</button>` : ''}
      </div>
    `;
  } else {
    const resumoDia = confAtiva.reservasDoDia.length > 0
      ? ('Outras reservas neste dia para ' + placaSel + ': ' + confAtiva.reservasDoDia.map(function(x) { return x.horarioSaida + '–' + x.horarioRetorno + ' (' + (x.unidade || x.solicitante) + ')'; }).join(' | '))
      : ('Agenda 100% livre para o veículo ' + placaSel + ' em ' + formatarDataCompletaBr(data) + '.');
    box.style.background = '#ecfdf5';
    box.style.borderColor = '#a7f3d0';
    box.innerHTML = `
      <div style="font-size: 0.79rem; color: #065f46; display: flex; align-items: center; gap: 0.45rem;">
        <span>✅</span>
        <span><strong>Veículo ${placaSel} disponível!</strong> ${escaparHtmlSimples(resumoDia)}</span>
      </div>
    `;
  }
}

function atualizarCamposVeiculoFormularioNovo() {
  const selVeiculo = document.getElementById('form-carro-veiculo');
  const inputKmPartida = document.getElementById('form-carro-km-partida');
  const inputTanque = document.getElementById('form-carro-tanque');
  const inputMotorista = document.getElementById('form-carro-motorista');
  
  if (!selVeiculo) return;
  const isSpin = selVeiculo.value.indexOf('Spin') !== -1;
  const vFrota = (CARRO_DATA.frota || []).find(f => isSpin ? f.placa.indexOf('TLH') !== -1 : f.placa.indexOf('FZG') !== -1);

  if (vFrota) {
    if (inputKmPartida) inputKmPartida.value = vFrota.kmNum || parseInt(String(vFrota.km).replace(/\D/g, ''), 10) || (isSpin ? 42850 : 28340);
    if (inputTanque) inputTanque.value = vFrota.combustivel || '85%';
    if (inputMotorista) {
      var condEx = vFrota.motorista || (isSpin ? 'Steve Rogers' : 'Barry Allen');
      inputMotorista.placeholder = 'Ex: ' + condEx + ' / Clark Kent';
      if (!inputMotorista.dataset.editadoManual) inputMotorista.value = '';
    }
  }
}

function salvarSolicitacaoCarro(event) {
  if (event) event.preventDefault();
  const destino = document.getElementById('form-carro-destino').value.trim();
  const data = document.getElementById('form-carro-data').value;
  const inDataRet = document.getElementById('form-carro-data-retorno');
  const dataRetorno = (inDataRet && inDataRet.value) ? inDataRet.value : data;
  const saida = document.getElementById('form-carro-saida').value;
  const retorno = document.getElementById('form-carro-retorno').value;
  const veiculoVal = document.getElementById('form-carro-veiculo').value;
  const solicitante = document.getElementById('form-carro-solicitante').value.trim();
  const funcao = document.getElementById('form-carro-funcao') ? document.getElementById('form-carro-funcao').value.trim() : '';
  const setor = document.getElementById('form-carro-setor').value;
  const motorista = document.getElementById('form-carro-motorista') ? document.getElementById('form-carro-motorista').value.trim() : '';
  const kmPartida = parseInt(document.getElementById('form-carro-km-partida') ? document.getElementById('form-carro-km-partida').value : '0', 10) || 0;
  const tanqueNivel = document.getElementById('form-carro-tanque') ? document.getElementById('form-carro-tanque').value.trim() : '80%';
  const tanqueCheio = document.getElementById('form-carro-tanque-cheio') ? document.getElementById('form-carro-tanque-cheio').value : 'S';
  const obs = document.getElementById('form-carro-obs').value.trim();
  const passageiros = parseInt(document.getElementById('form-carro-passageiros') ? document.getElementById('form-carro-passageiros').value : '1', 10) || 1;
  const contato = document.getElementById('form-carro-contato') ? document.getElementById('form-carro-contato').value.trim() : '';
  const prioridade = document.getElementById('form-carro-prioridade') ? document.getElementById('form-carro-prioridade').value : 'Normal';
  const apresentarEm = document.getElementById('form-carro-apresentar') ? document.getElementById('form-carro-apresentar').value.trim() : 'URE - ITP - Rua Dimarães Antônio Sandei, 75';
  const itinerarioInput = document.getElementById('form-carro-itinerario') ? document.getElementById('form-carro-itinerario').value.trim() : '';

  if (!destino || !data || !dataRetorno || !solicitante) {
    abrirModalAvisoCarroUX({
      tipo: 'aviso',
      icone: '📝',
      eyebrow: 'CAMPOS OBRIGATÓRIOS',
      titulo: 'Preencha os dados da viagem',
      html: '<p style="margin: 0; color: #334155; font-size: 0.9rem; line-height: 1.55;">Para confirmar o agendamento, informe o <strong>Destino</strong>, as datas de <strong>Ida e Retorno</strong> e o <strong>Nome do Solicitante</strong>.</p>',
      textoFechar: 'Entendi • Voltar'
    });
    return;
  }
  if (dataRetorno < data) {
    abrirModalAvisoCarroUX({
      tipo: 'aviso',
      icone: '📅',
      eyebrow: 'VALIDAÇÃO DE PERÍODO',
      titulo: 'Data de retorno inválida',
      html: '<p style="margin: 0; color: #334155; font-size: 0.9rem; line-height: 1.55;">A <strong>Data de Retorno</strong> não pode ser anterior à <strong>Data de Ida</strong>. Ajuste o período selecionado.</p>',
      textoFechar: 'Ajustar Datas'
    });
    return;
  }
  if (dataRetorno === data && horarioParaMinutos(retorno) <= horarioParaMinutos(saida)) {
    abrirModalAvisoCarroUX({
      tipo: 'aviso',
      icone: '⏰',
      eyebrow: 'VALIDAÇÃO DE HORÁRIO',
      titulo: 'Horário de retorno inválido',
      html: '<p style="margin: 0; color: #334155; font-size: 0.9rem; line-height: 1.55;">Para viagens no mesmo dia, o <strong>Horário de Retorno</strong> deve ser posterior ao <strong>Horário de Saída</strong>.</p>',
      textoFechar: 'Ajustar Horários'
    });
    return;
  }

  const isSpin = veiculoVal.indexOf('Spin') !== -1;
  const placa = isSpin ? 'TLH 1B63' : 'FZG 0H22';
  if (!isSpin && passageiros > 5) {
    abrirModalAvisoCarroUX({
      tipo: 'aviso',
      icone: '👥',
      eyebrow: 'CAPACIDADE DO VEÍCULO',
      titulo: 'Lotação excedida para o Hyundai HB20',
      html: '<p style="margin: 0 0 0.85rem 0; color: #334155; font-size: 0.9rem; line-height: 1.55;">O veículo <strong>Hyundai HB20 1.0 (FZG 0H22)</strong> comporta no máximo <strong>5 ocupantes</strong>.</p><p style="margin: 0; color: #475569; font-size: 0.84rem;">Deseja trocar automaticamente para a <strong>Chevrolet Spin (7 lugares)</strong>?</p>',
      textoConfirmar: '🚗 Trocar para Spin (7 lugares)',
      textoFechar: 'Ajustar Passageiros',
      onConfirmar: function() {
        selecionarVeiculoSolicitacaoCarro('Chevrolet Spin 1.8 7L (Oficial Gabinete)');
      }
    });
    return;
  }

  const conf = verificarConflitoAgendaCarro(data, saida, retorno, placa, null, dataRetorno);
  if (conf.temConflito) {
    const c = conf.conflitantes[0];
    const cDataIda = formatarDataCompletaBr(c.data);
    const cDataRet = formatarDataCompletaBr(c.dataRetorno || c.data);
    const periodoConflito = (cDataRet !== cDataIda)
      ? (cDataIda + ' (' + c.horarioSaida + ') até ' + cDataRet + ' (' + c.horarioRetorno + ')')
      : (cDataIda + ' • ' + c.horarioSaida + ' às ' + c.horarioRetorno);
    const outroPlaca = isSpin ? 'FZG 0H22' : 'TLH 1B63';
    const outroNome = isSpin ? 'Hyundai HB20 1.0 (FZG 0H22)' : 'Chevrolet Spin 1.8 7L (TLH 1B63)';
    const outroValor = isSpin ? 'Hyundai HB20 1.0 (Oficial Apoio)' : 'Chevrolet Spin 1.8 7L (Oficial Gabinete)';
    const confOutro = verificarConflitoAgendaCarro(data, saida, retorno, outroPlaca, null, dataRetorno);

    const conflitoHtml = `
      <p style="margin: 0 0 0.9rem 0; color: #334155; font-size: 0.88rem; line-height: 1.5;">
        O veículo solicitado já possui um deslocamento oficial confirmado que sobrepõe este período:
      </p>
      <div style="background: #fef2f2; border: 1px solid #fecaca; border-left: 4px solid #dc2626; border-radius: 10px; padding: 0.9rem 1rem; margin-bottom: 0.9rem; display: grid; gap: 0.45rem;">
        <div style="display: flex; justify-content: space-between; align-items: center; gap: 0.5rem; flex-wrap: wrap;">
          <span style="background: #0b2351; color: #fde047; font-family: monospace; font-size: 0.78rem; font-weight: 800; padding: 0.16rem 0.55rem; border-radius: 5px;">${escaparHtmlSimples(placa)}</span>
          <span style="font-size: 0.74rem; font-weight: 800; color: #991b1b; background: #fee2e2; padding: 0.14rem 0.55rem; border-radius: 9999px;">${escaparHtmlSimples(c.controleTrafegoNum || 'CT-2026')}</span>
        </div>
        <div style="font-size: 0.86rem; font-weight: 800; color: #0f172a;">👤 ${escaparHtmlSimples(c.solicitante || 'Gabinete')}</div>
        <div style="font-size: 0.8rem; color: #475569;">🏢 ${escaparHtmlSimples(c.unidade || c.setor || 'URE - ITP')}</div>
        <div style="font-size: 0.82rem; font-weight: 700; color: #b91c1c;">⏰ ${escaparHtmlSimples(periodoConflito)}</div>
        <div style="font-size: 0.78rem; color: #64748b;">📍 ${escaparHtmlSimples(c.destino || 'Deslocamento Oficial')}</div>
      </div>
      <div style="background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; padding: 0.7rem 0.85rem; font-size: 0.81rem; color: #334155;">
        ${!confOutro.temConflito
          ? ('💡 <strong>Sugestão:</strong> O veículo <strong>' + outroNome + '</strong> está <strong>livre</strong> neste horário. Você pode selecioná-lo agora com 1 clique.')
          : '💡 Escolha outro horário ou ajuste a data da viagem para evitar sobreposição na frota.'}
      </div>
    `;

    abrirModalAvisoCarroUX({
      tipo: 'conflito',
      icone: '🚫',
      eyebrow: 'CONFLITO DE AGENDA • FROTA OFICIAL',
      titulo: 'Veículo ' + placa + ' indisponível no horário',
      html: conflitoHtml,
      textoConfirmar: !confOutro.temConflito ? ('🚗 Trocar para ' + outroPlaca) : null,
      textoFechar: !confOutro.temConflito ? 'Fechar / Ajustar' : 'Fechar e Ajustar Horário',
      onConfirmar: !confOutro.temConflito ? function() {
        selecionarVeiculoSolicitacaoCarro(outroValor);
        mostrarToastAgenda('Veículo alterado para ' + outroNome + '. Confira e confirme a reserva!', '🚗');
      } : null
    });
    return;
  }

  const modelo = isSpin ? 'Chevrolet Spin 1.8 7L' : 'Hyundai HB20 1.0';
  const patrimonio = isSpin ? 'SP-048972' : 'SP-051204';
  const tipo = isSpin ? 'Oficial Gabinete' : 'Oficial Apoio / Administrativo';
  const grupo = isSpin ? 'Gabinete Dirigente' : 'Regional / Apoio';
  const condutorDef = motorista || (isSpin ? 'Steve Rogers' : 'Barry Allen');

  const novoNumSeq = (CARRO_DATA.registros || []).length + 46;
  const novoCt = 'CT-2026/' + String(novoNumSeq).padStart(3, '0');
  const novoId = 'car-' + Date.now();

  const novoRegistro = {
    id: novoId,
    controleTrafegoNum: novoCt,
    data: data,
    dataRetorno: dataRetorno,
    periodo: data + ' a ' + dataRetorno,
    titulo: 'Reserva de Carro Oficial: ' + destino,
    veiculo: modelo,
    placa: placa,
    patrimonio: patrimonio,
    tipo: tipo,
    grupo: grupo,
    motorista: condutorDef,
    solicitante: solicitante,
    funcao: funcao || (solicitante.indexOf('Dirigente') !== -1 ? 'Dirigente Regional' : 'Responsável Técnico'),
    unidade: setor || 'Gabinete / URE Itapevi',
    passageiros: passageiros,
    contato: contato || 'URE Itapevi',
    prioridade: prioridade,
    apresentarEm: apresentarEm || 'URE - ITP - Rua Dimarães Antônio Sandei, 75',
    destino: destino,
    itinerario: itinerarioInput || ('URE - ITP -> ' + destino + ' -> Retorno URE - ITP'),
    horarioSaida: saida || '08:00',
    horarioRetorno: retorno || '17:00',
    kmPartida: kmPartida || (isSpin ? 42850 : 28340),
    kmRetorno: kmPartida || (isSpin ? 42850 : 28340),
    kmDiferenca: 0,
    tanqueCheio: tanqueCheio,
    combustivelNivel: tanqueNivel,
    abastecimento: { natureza: 'Gasolina', quant: '', reqNum: '', nfNum: '', expedidor: 'SEOM / Logística' },
    origemFonte: 'Sistema de Agendamento',
    tipoRegistro: 'Reserva de carro oficial',
    badgeOrigem: 'Agendamento Oficial',
    status: 'Agendado',
    observacoes: obs || 'Solicitação registrada diretamente no sistema oficial da URE Itapevi.'
  };

  CARRO_DATA.registros.unshift(novoRegistro);
  salvarCarroStorage();
  fecharModalCarro();

  dataAtivaCarro = data;
  var pData = data.split('-');
  if (pData.length === 3) {
    anoAtivoCarro = parseInt(pData[0], 10);
    mesAtivoCarro = parseInt(pData[1], 10) - 1;
  }
  modoVisaoCalCarro = 'grade';
  subTabAtivaCarro = 'calendario';
  renderizarCarroOficial();
  mostrarToastAgenda('Solicitação ' + novoCt + ' registrada na nuvem para ' + formatarDataCompletaBr(data) + '!', '✅');
}

/* ============================================================== */
/* MODAL DE EDIÇÃO PÓS-SOLICITAÇÃO                                */
/* ============================================================== */

function abrirModalEditarSolicitacaoCarro(idRegistro) {
  const reg = (CARRO_DATA.registros || []).find(r => r.id === idRegistro);
  if (!reg) {
    abrirModalAvisoCarroUX({
      tipo: 'aviso',
      icone: '🔍',
      eyebrow: 'REGISTRO NÃO ENCONTRADO',
      titulo: 'Deslocamento indisponível',
      html: '<p style="margin: 0; color: #334155; font-size: 0.9rem;">O agendamento selecionado não foi encontrado na base ativa.</p>'
    });
    return;
  }

  const modal = document.getElementById('modal-editar-solicitacao-carro');
  if (!modal) return;

  document.getElementById('edit-carro-id').value = reg.id;
  document.getElementById('edit-carro-ct-badge').innerText = reg.controleTrafegoNum || 'CT-2026/042';
  document.getElementById('edit-carro-data').value = reg.data || '';
  if (document.getElementById('edit-carro-data-retorno')) {
    document.getElementById('edit-carro-data-retorno').value = reg.dataRetorno || reg.data || '';
  }
  
  const selVeiculo = document.getElementById('edit-carro-veiculo');
  if (selVeiculo) {
    const isSpin = (reg.veiculo && reg.veiculo.indexOf('Spin') !== -1) || (reg.placa && reg.placa.indexOf('TLH') !== -1);
    selVeiculo.value = isSpin ? 'TLH 1B63' : 'FZG 0H22';
  }

  document.getElementById('edit-carro-motorista').value = reg.motorista || '';
  document.getElementById('edit-carro-solicitante').value = reg.solicitante || '';
  document.getElementById('edit-carro-funcao').value = reg.funcao || '';
  document.getElementById('edit-carro-unidade').value = reg.unidade || reg.setor || '';
  document.getElementById('edit-carro-apresentar').value = reg.apresentarEm || 'URE - ITP - Rua Dimarães Antônio Sandei, 75';
  document.getElementById('edit-carro-saida').value = reg.horarioSaida || '08:00';
  document.getElementById('edit-carro-retorno').value = reg.horarioRetorno || '17:00';
  document.getElementById('edit-carro-destino').value = reg.destino || '';
  document.getElementById('edit-carro-itinerario').value = reg.itinerario || '';
  
  /* Hodômetro e combustível */
  const inKmPartida = document.getElementById('edit-carro-km-partida');
  const inKmRetorno = document.getElementById('edit-carro-km-retorno');
  const inKmDif = document.getElementById('edit-carro-km-diferenca');
  
  inKmPartida.value = reg.kmPartida !== undefined ? reg.kmPartida : 0;
  inKmRetorno.value = reg.kmRetorno !== undefined ? reg.kmRetorno : (reg.kmPartida || 0);
  inKmDif.value = reg.kmDiferenca !== undefined ? reg.kmDiferenca : Math.max(0, (inKmRetorno.value - inKmPartida.value));

  document.getElementById('edit-carro-tanque-nivel').value = reg.combustivelNivel || '80%';
  document.getElementById('edit-carro-tanque-cheio').value = reg.tanqueCheio || 'S';
  document.getElementById('edit-carro-status').value = reg.status || 'Agendado';
  document.getElementById('edit-carro-obs').value = reg.observacoes || '';
  if (document.getElementById('edit-carro-defeitos')) {
    document.getElementById('edit-carro-defeitos').value = reg.defeitos !== undefined ? reg.defeitos : 'Nenhum defeito ou avaria identificado durante o percurso.';
  }
  if (document.getElementById('edit-carro-multas')) {
    document.getElementById('edit-carro-multas').value = reg.multas !== undefined ? reg.multas : 'Sem ocorrências de trânsito, multas ou sinistros.';
  }

  /* Abastecimento */
  const ab = reg.abastecimento || {};
  if (document.getElementById('edit-carro-abast-natureza')) document.getElementById('edit-carro-abast-natureza').value = ab.natureza || 'Gasolina';
  if (document.getElementById('edit-carro-abast-quant')) document.getElementById('edit-carro-abast-quant').value = ab.quant || '';
  if (document.getElementById('edit-carro-abast-req')) document.getElementById('edit-carro-abast-req').value = ab.reqNum || '';
  if (document.getElementById('edit-carro-abast-nf')) document.getElementById('edit-carro-abast-nf').value = ab.nfNum || '';
  if (document.getElementById('edit-carro-abast-expedidor')) document.getElementById('edit-carro-abast-expedidor').value = ab.expedidor || 'SEOM / Logística';

  modal.style.display = 'flex';
}

function fecharModalEditarCarro() {
  const modal = document.getElementById('modal-editar-solicitacao-carro');
  if (modal) modal.style.display = 'none';
}

function recalcularKmEdicaoCarro() {
  const p = parseInt(document.getElementById('edit-carro-km-partida').value || '0', 10);
  const r = parseInt(document.getElementById('edit-carro-km-retorno').value || '0', 10);
  const dif = Math.max(0, r - p);
  const outDif = document.getElementById('edit-carro-km-diferenca');
  if (outDif) outDif.value = dif;
}

function salvarEdicaoSolicitacaoCarro(event) {
  if (event) event.preventDefault();
  const id = document.getElementById('edit-carro-id').value;
  const reg = (CARRO_DATA.registros || []).find(r => r.id === id);
  if (!reg) return;

  const placaSel = document.getElementById('edit-carro-veiculo').value;
  const isSpin = placaSel.indexOf('TLH') !== -1;

  reg.veiculo = isSpin ? 'Chevrolet Spin 1.8 7L' : 'Hyundai HB20 1.0';
  reg.placa = isSpin ? 'TLH 1B63' : 'FZG 0H22';
  reg.patrimonio = isSpin ? 'SP-048972' : 'SP-051204';
  reg.tipo = isSpin ? 'Oficial Gabinete' : 'Oficial Apoio / Administrativo';
  reg.grupo = isSpin ? 'Gabinete Dirigente' : 'Regional / Apoio';

  reg.data = document.getElementById('edit-carro-data').value;
  var editRetVal = document.getElementById('edit-carro-data-retorno') ? document.getElementById('edit-carro-data-retorno').value : reg.data;
  reg.dataRetorno = (editRetVal && editRetVal >= reg.data) ? editRetVal : reg.data;
  reg.periodo = reg.data + ' a ' + reg.dataRetorno;
  reg.motorista = document.getElementById('edit-carro-motorista').value.trim();
  reg.solicitante = document.getElementById('edit-carro-solicitante').value.trim();
  reg.funcao = document.getElementById('edit-carro-funcao').value.trim();
  reg.unidade = document.getElementById('edit-carro-unidade').value.trim();
  reg.apresentarEm = document.getElementById('edit-carro-apresentar').value.trim();
  reg.horarioSaida = document.getElementById('edit-carro-saida').value;
  reg.horarioRetorno = document.getElementById('edit-carro-retorno').value;
  reg.destino = document.getElementById('edit-carro-destino').value.trim();
  reg.itinerario = document.getElementById('edit-carro-itinerario').value.trim();

  /* Hodômetro & Tanque */
  const kmP = parseInt(document.getElementById('edit-carro-km-partida').value || '0', 10);
  const kmR = parseInt(document.getElementById('edit-carro-km-retorno').value || '0', 10);
  reg.kmPartida = kmP;
  reg.kmRetorno = kmR;
  reg.kmDiferenca = Math.max(0, kmR - kmP);
  reg.combustivelNivel = document.getElementById('edit-carro-tanque-nivel').value.trim();
  reg.tanqueCheio = document.getElementById('edit-carro-tanque-cheio').value;
  reg.status = document.getElementById('edit-carro-status').value;
  reg.observacoes = document.getElementById('edit-carro-obs').value.trim();
  reg.defeitos = document.getElementById('edit-carro-defeitos') ? document.getElementById('edit-carro-defeitos').value.trim() : '';
  reg.multas = document.getElementById('edit-carro-multas') ? document.getElementById('edit-carro-multas').value.trim() : '';

  /* Abastecimento */
  reg.abastecimento = {
    natureza: document.getElementById('edit-carro-abast-natureza') ? document.getElementById('edit-carro-abast-natureza').value : 'Gasolina',
    quant: document.getElementById('edit-carro-abast-quant') ? document.getElementById('edit-carro-abast-quant').value.trim() : '',
    reqNum: document.getElementById('edit-carro-abast-req') ? document.getElementById('edit-carro-abast-req').value.trim() : '',
    nfNum: document.getElementById('edit-carro-abast-nf') ? document.getElementById('edit-carro-abast-nf').value.trim() : '',
    expedidor: document.getElementById('edit-carro-abast-expedidor') ? document.getElementById('edit-carro-abast-expedidor').value.trim() : 'SEOM'
  };

  /* Se o hodômetro de retorno foi atualizado e maior que o atual da frota, sincroniza a frota */
  const vFrota = (CARRO_DATA.frota || []).find(f => f.placa === reg.placa);
  if (vFrota && kmR > (vFrota.kmNum || 0)) {
    vFrota.kmNum = kmR;
    vFrota.km = kmR.toLocaleString('pt-BR') + ' km';
    vFrota.combustivel = reg.combustivelNivel;
    vFrota.tanqueCheio = reg.tanqueCheio === 'S' ? 'Sim' : 'Não';
    if (reg.status === 'Em Trânsito') vFrota.status = 'Em Uso Oficial';
    if (reg.status === 'Concluído') vFrota.status = 'Disponível no Pátio';
  }

  salvarCarroStorage();
  fecharModalEditarCarro();
  renderizarCarroOficial();
  mostrarToastAgenda('Agendamento ' + (reg.controleTrafegoNum || '') + ' atualizado com sucesso!', '🚗');
}

