function concluirViagemRapida(idRegistro) {
  const reg = (CARRO_DATA.registros || []).find(r => r.id === idRegistro);
  if (!reg) return;

  const sugestaoKm = reg.kmRetorno && reg.kmRetorno > (reg.kmPartida || 0) ? reg.kmRetorno : ((reg.kmPartida || 0) + 35);
  abrirModalAvisoCarroUX({
    tipo: 'concluir',
    icone: '🏁',
    eyebrow: 'ENCERRAMENTO DE DESLOCAMENTO • ' + (reg.controleTrafegoNum || 'CT-2026'),
    titulo: 'Concluir Viagem & Registrar Km',
    html: `
      <div style="background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 0.8rem 0.95rem; margin-bottom: 0.95rem; font-size: 0.82rem; color: #334155;">
        <div><strong>Veículo:</strong> ${escaparHtmlSimples(reg.veiculo)} (${escaparHtmlSimples(reg.placa || '')})</div>
        <div style="margin-top: 0.25rem;"><strong>Hodômetro de Partida:</strong> <span style="font-family: monospace; font-weight: 800; color: #0b2351;">${reg.kmPartida || 0} km</span></div>
      </div>
      <label class="agenda-form-label" style="display: block; margin-bottom: 0.35rem;">Informe o Hodômetro de Retorno (km) *</label>
      <input type="number" id="ux-carro-km-retorno-input" class="agenda-form-input" value="${sugestaoKm}" min="${reg.kmPartida || 0}" style="font-size: 1rem; font-weight: 700;">
      <div id="ux-carro-km-erro" style="display: none; color: #dc2626; font-size: 0.78rem; font-weight: 700; margin-top: 0.4rem;"></div>
    `,
    textoConfirmar: '🏁 Confirmar Conclusão',
    textoFechar: 'Cancelar',
    onConfirmar: function() {
      const inKm = document.getElementById('ux-carro-km-retorno-input');
      const errEl = document.getElementById('ux-carro-km-erro');
      const kmRetorno = parseInt(String(inKm ? inKm.value : '').replace(/\D/g, ''), 10);
      if (isNaN(kmRetorno) || kmRetorno < (reg.kmPartida || 0)) {
        if (errEl) {
          errEl.innerText = '⚠️ O hodômetro de retorno deve ser maior ou igual a ' + (reg.kmPartida || 0) + ' km.';
          errEl.style.display = 'block';
        }
        return false;
      }

      reg.kmRetorno = kmRetorno;
      reg.kmDiferenca = kmRetorno - (reg.kmPartida || 0);
      reg.status = 'Concluído';

      const vFrota = (CARRO_DATA.frota || []).find(f => f.placa === reg.placa);
      if (vFrota && kmRetorno > (vFrota.kmNum || 0)) {
        vFrota.kmNum = kmRetorno;
        vFrota.km = kmRetorno.toLocaleString('pt-BR') + ' km';
        vFrota.status = 'Disponível no Pátio';
      }

      salvarCarroStorage();
      renderizarCarroOficial();
      mostrarToastAgenda('Deslocamento concluído! Diferença: ' + reg.kmDiferenca + ' km rodados.', '🏁');
    }
  });
}

